export function step(state, dt) {
  const { ball, paddle } = state;

  // Position before the move: brick collision sweeps the path between the
  // two samples, so a fast ball cannot jump over a brick in one step.
  const prev = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  ... (unchanged)

  // Ceiling
  ... (unchanged)

  // Paddle
  ... (unchanged)

  // Bricks: swept collision (moved out of frame(); debt #2 paid).
  // Each hit kills the brick and bounces the ball exactly once: the sweep
  // origin is reset after every resolution, so a ball resting on a grid seam
  // (BRICK_GAP = 8 < ball diameter = 14) bounces on the first brick and no
  // longer overlaps the second — one flip per axis per pass.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (!Number.isFinite(sweptTime(prev, ball, brick))) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (collides(ball, brick)) {
      // The ball rests inside the brick: resolve by the least-penetration
      // axis (both axes on a corner) and push it back out.
      resolveOverlap(ball, brick);
    } else {
      // The ball crossed the brick between two samples without ever resting
      // inside it (tunneling): bounce at the entry face of the sweep.
      resolveCrossing(ball, prev, brick);
    }

    // Judge the next brick from where the ball actually is now.
    prev.x = ball.x;
    prev.y = ball.y;
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
