// Resolves a contact where the ball rests inside the brick: flips the
// least-penetrated axis (both on a corner, where the penetrations tie) and
// pushes the ball back out to the touched face.
function resolveOverlap(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // Side hit: the ball is closer to the left or the right face.
    if (penLeft < penRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (penY < penX) {
    // Top/bottom hit: the ball is closer to the top or the bottom face.
    if (penTop < penBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // Corner: equal penetration on both axes, both components flip.
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Resolves a tunneling contact: the ball crossed the brick between two
// samples without ever resting inside it. The entry face is the axis whose
// overlap started last; the ball is repositioned at the touched face.
function resolveCrossing(ball, prev, brick) {
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;
  const entryX = dx > 0 ? (brick.x - ball.r - prev.x) / dx
    : dx < 0 ? (brick.x + brick.w + ball.r - prev.x) / dx
    : 0;
  const entryY = dy > 0 ? (brick.y - ball.r - prev.y) / dy
    : dy < 0 ? (brick.y + brick.h + ball.r - prev.y) / dy
    : 0;

  // The axis whose overlap started last is the face the ball entered through.
  if (entryY > entryX) {
    if (dy > 0) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else if (entryX > entryY) {
    if (dx > 0) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}
