// --- Brick collision resolution (swept) ------------------------------------

// Resolves a contact where the ball rests inside the brick: flips the
// least-penetrated axis (both on a corner, where the penetrations tie) and
// pushes the ball back out to the touched face.
function resolveOverlap(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // Side hit: the ball is closer to the left or the right face.
    if (penLeft < penRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (penY < penX) {
    // Top/bottom hit: the ball is closer to the top or the bottom face.
    if (penTop < penBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // Corner: equal penetration on both axes, both components flip.
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Slab test: first time along the move from `prev` to the ball's current
// position at which the ball's box (radius `ball.r`) touches the brick.
// Returns a fraction in [0, 1] (negative when the ball already overlapped at
// the start of the move) or Infinity when the swept boxes never overlap.
function sweptTime(prev, ball, brick) {
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  const entryX = dx > 0 ? (brick.x - ball.r - prev.x) / dx
    : dx < 0 ? (brick.x + brick.w + ball.r - prev.x) / dx
    : prev.x + ball.r > brick.x && prev.x - ball.r < brick.x + brick.w ? 0 : Infinity;
  const exitX = dx > 0 ? (brick.x + brick.w + ball.r - prev.x) / dx
    : dx < 0 ? (brick.x - ball.r - prev.x) / dx
    : Infinity;
  const entryY = dy > 0 ? (brick.y - ball.r - prev.y) / dy
    : dy < 0 ? (brick.y + brick.h + ball.r - prev.y) / dy
    : prev.y + ball.r > brick.y && prev.y - ball.r < brick.y + brick.h ? 0 : Infinity;
  const exitY = dy > 0 ? (brick.y + brick.h + ball.r - prev.y) / dy
    : dy < 0 ? (brick.y - ball.r - prev.y) / dy
    : Infinity;

  const entry = Math.max(entryX, entryY);
  const exit = Math.min(exitX, exitY);
  return entry <= 1 && entry < exit ? entry : Infinity;
}

// Resolves a tunneling contact: the ball crossed the brick between two
// samples without ever resting inside it. The entry face is the axis whose
// overlap started last; the ball is repositioned at the touched face.
function resolveCrossing(ball, prev, brick) {
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;
  const entryX = dx > 0 ? (brick.x - ball.r - prev.x) / dx
    : dx < 0 ? (brick.x + brick.w + ball.r - prev.x) / dx
    : 0;
  const entryY = dy > 0 ? (brick.y - ball.r - prev.y) / dy
    : dy < 0 ? (brick.y + brick.h + ball.r - prev.y) / dy
    : 0;

  if (entryY > entryX) {
    if (dy > 0) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else if (entryX > entryY) {
    if (dx > 0) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (collision and scoring moved out of
// `frame()`, debt #2 paid).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Position before the move: brick collision sweeps the path between the two
  // samples, so a fast ball cannot jump over a brick in one step (tunneling).
  const prev = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;

[157 more lines in file. Use offset=290 to continue.]

    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: collision + bounce + score, moved out of `frame()`. The sweep
  // origin is reset after every resolution, so a ball resting on a grid seam
  // (BRICK_GAP = 8 < ball diameter = 14) bounces on the first brick and no
  // longer overlaps the second — one flip per axis per pass.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    // A contact is either a resting overlap (the wall/ceiling clamps can put
    // the ball inside a brick between integration and this loop) or a
    // crossing of the swept path (tunneling).
    if (!collides(ball, brick) && !Number.isFinite(sweptTime(prev, ball, brick))) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (collides(ball, brick)) {
      // The ball rests inside the brick: resolve by the least-penetration
      // axis (both axes on a corner) and push it back out.
      resolveOverlap(ball, brick);
    } else {
      // The ball crossed the brick between two samples without ever resting
      // inside it (tunneling): bounce at the entry face of the sweep.
      resolveCrossing(ball, prev, brick);
    }

    // Judge the next brick from where the ball actually is now.
    prev.x = ball.x;
    prev.y = ball.y;
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop: pure drawing. Collision, bounce and scoring live in
// `step()`; this function only reads the state.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: rendering only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

